let dGroup='basic';
function dMatrix(){
 const mobile=matchMedia('(max-width:760px)').matches,ids=mobile?[$('#d-left').value,$('#d-right').value]:dIds;
 $('#d-matrix').innerHTML=`<div class="d-matrixrow d-matrixhead"><div>البند</div>${ids.map(id=>`<div>${esc(dNames[id])}</div>`).join('')}</div>`+dParts.filter(p=>dGroup==='all'||p.group===dGroup).map(part=>{
  const comparable=ids.map(id=>part.cells[id]).filter(Boolean).filter(c=>!c.max&&!c.retail),minimum=comparable.length>1?Math.min(...comparable.map(c=>c.price)):null;
  return `<div class="d-matrixrow"><div class="d-partlabel"><h3>${esc(part.label)}</h3><p>${esc(part.note)}</p></div>${ids.map(id=>{const c=part.cells[id],low=c&&!c.retail&&minimum!==null&&!c.max&&c.price===minimum;return `<div class="d-partcell ${low?'islowest':''}">${c?`<span class="d-price">${c.max?`${nf.format(c.price)}<br>إلى ${dSmallMoney(c.max)}`:dSmallMoney(c.price)}</span>${low?'<span class="d-lowest">الأقل من أسعار الكتالوج</span>':''}${c.retail?`<span class="d-offer-status">${esc(c.stock)} · سعر بائع</span><span class="d-unit">توافق البائع فقط؛ ليس كودًا مطابقًا مثبتًا.</span>`:''}${c.max?`<span class="d-unit">${esc(c.note)}</span>`:''}<details class="d-cellinfo"><summary>${c.retail?'التوافق والمصدر':'الكود والمصدر'}</summary>${c.note&&!c.max?`<span class="d-unit">${esc(c.note)}</span>`:''}<span class="d-codes">${c.codes.map(esc).join('<br>')}</span><a href="${esc(c.url||DATA.sources.catalog.url)}" target="_blank" rel="noopener">${c.retail?'Wheels · فحص 15 نوفمبر':'الكتالوج'} ↗</a></details>`:'<span class="d-missing">غير موثق</span><span class="d-unit">لا نحسبه بصفر</span>'}</div>`}).join('')}</div>`
 }).join('');
}
