const dDefaults={fiddle:3,dd:3,evo:2.5,x:3};
$('#d-running-grid').innerHTML=dIds.map(id=>`<article class="d-costcard"><h3>${esc(dNames[id])}</h3><label>لتر لكل 100 كم<input type="number" id="d-rate-${id}" min="0" step="0.1" value="${dDefaults[id]}" inputmode="decimal"></label><span class="d-rate-source" id="d-rate-source-${id}"></span><span class="d-monthly-label">بنزين شهريًا</span><output class="d-monthly" id="d-month-${id}"></output><span class="d-yearly" id="d-year-${id}"></span><details><summary>أضف ميزانية صيانة</summary><label class="d-service-input">صيانة وقطع ومصنعية شهريًا<input type="number" id="d-maint-${id}" min="0" step="0.01" placeholder="غير موثقة، أدخل عرضك" inputmode="decimal"></label></details><div class="d-result">إجمالي التشغيل / شهر<b id="d-total-${id}">غير مكتمل</b><span class="d-firstyear" id="d-first-${id}"></span></div></article>`).join('');
function dNumber(el){const raw=el.value.trim(),n=Number(raw),valid=raw!==''&&Number.isFinite(n)&&n>=0&&n<=Number.MAX_SAFE_INTEGER;el.setAttribute('aria-invalid',String(raw!==''&&!valid));return valid?n:null}
function dRunning(){
 const km=dNumber($('#d-km')),petrol=dNumber($('#d-petrol')),fuelCosts={},complete=[];
 for(const id of dIds){
  const rate=dNumber($('#d-rate-'+id)),maint=dNumber($('#d-maint-'+id));
  const raw=km!==null&&petrol!==null&&rate!==null?km*rate/100*petrol:null;
  const fuel=raw!==null&&Number.isFinite(raw)&&Number.isFinite(raw*12)?raw:null;fuelCosts[id]=fuel;
  const rateSource=$('#d-rate-source-'+id);rateSource.classList.toggle('claim',id==='evo'&&rate===2.5);
  rateSource.innerHTML=id==='evo'&&rate===2.5?`${link('wevo','ادعاء بائع: 40 كم/لتر')}<br>مش قياسًا مستقلًا`:rate===dDefaults[id]?'افتراض ميزانية فقط.<br>ليس استهلاكًا فعليًا موثقًا.':'مدخل شخصي منك.<br>ليس استهلاكًا تحققنا منه.';
  $('#d-month-'+id).innerHTML=fuel===null?'غير محدد':dSmallMoney(fuel);
  $('#d-year-'+id).textContent=fuel===null?'راجع المسافة والسعر والاستهلاك.':`${nf.format(fuel*12)} ج.م بنزين سنويًا`;
  const total=fuel!==null&&maint!==null?fuel+maint:null,first=total!==null?dBuy[id]+total*12:null;
  const valid=total!==null&&Number.isFinite(total)&&Number.isFinite(first);
  $('#d-total-'+id).innerHTML=valid?dSmallMoney(total):'غير مكتمل';
  $('#d-first-'+id).textContent=valid?`شراء + تشغيل أول سنة: ${nf.format(first)} ج.م؛ دون ترخيص وتأمين وإضافات.`:'الصيانة غير محسومة؛ البنزين وحده ليس تكلفة التشغيل.';
  if(valid)complete.push({id,total});
 }
 const diff=fuelCosts.fiddle!==null&&fuelCosts.evo!==null?fuelCosts.fiddle-fuelCosts.evo:null;
 const base=diff!==null?`حسب المدخلات: ${diff>=0?'بنزين EVO أقل من فيدل':'بنزين فيدل أقل من EVO'} بـ${nf.format(Math.abs(diff))} ج.م شهريًا (${nf.format(Math.abs(diff)*12)} سنويًا). فرق شراء EVO: ${nf.format(dBuy.evo-dBuy.fiddle)} ج.م.`:'أدخل مسافة وسعرًا ومعدلات استهلاك صحيحة.';
 const lowest=complete.length===4?Math.min(...complete.map(r=>r.total)):null,winners=complete.filter(r=>lowest!==null&&Math.abs(r.total-lowest)<0.005);
 $('#d-running-summary').textContent=base+(complete.length===4?` بعد إدخال صيانة الأربعة، ${winners.length>1?'الأقل بالتساوي':'الأقل تشغيلًا'} في سيناريوك: ${winners.map(r=>dNames[r.id]).join(' و')}.`:' إجمالي التشغيل لا يكتمل من غير ميزانية الصيانة.');
}
