function dOil(){
 const km=dNumber($('#d-oil-km')),price=dNumber($('#d-oil-price')),labor=dNumber($('#d-oil-labor')),blank=$('#d-oil-labor').value.trim()==='';
 $('#d-oil-results').innerHTML=[1000,5000].map(interval=>{
  const cycles=km===null?null:km/interval,oil=cycles!==null&&price!==null?cycles*price:null,total=oil!==null&&labor!==null?oil+cycles*labor:null;
  const valid=oil!==null&&Number.isFinite(oil)&&(blank||total!==null&&Number.isFinite(total));
  return `<article><span class="d-kicker">فرضية: كل ${nf.format(interval)} كم</span><strong>${valid?dSmallMoney(oil):'راجع المدخلات'}</strong><span>مخصص زيت سنوي حسب المسافة فقط</span><p>${valid?`${nf.format(cycles)} دورة مكافئة سنويًا؛ ليست عدد زيارات.`:'أدخل مسافة وسعر عبوة صحيحين، ومصنعية صحيحة أو اتركها فارغة.'}</p><b>${valid&&!blank?`مع المصنعية المدخلة: ${nf.format(total)} ج.م / سنة`:'المصنعية غير محسوبة'}</b></article>`;
 }).join('');
}
