 const all=aAudit.rows.filter(r=>(!model||r.modelIds.includes(model))&&(!kind||r.condition===kind)&&(!q||(r.label+' '+r.name+' '+r.modelIds.map(id=>aNames[id]).join(' ')).toLowerCase().includes(q)));
 const max=Math.max(1,Math.ceil(all.length/8));aPage=Math.min(aPage,max);
 $('#d-audit-count').textContent=`${nf.format(all.length)} عرضًا من ${nf.format(aAudit.rows.length)} · سعر إدراج شامل الضريبة · لا يشمل تركيبًا أو شحنًا غير منشور`;
